  CONSTRAINT `productID_PRP` FOREIGN KEY (`productID`) REFERENCES `product` (`productID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `productsupplier` (
  `productID` varchar(15) NOT NULL,
  `supplierID` varchar(15) NOT NULL,
