  KEY `productID_PS_idx` (`productID`),
  KEY `supplierID_PS_idx` (`supplierID`),
  CONSTRAINT `productID_SP` FOREIGN KEY (`productID`) REFERENCES `product` (`productID`),
  CONSTRAINT `supplierID_SP` FOREIGN KEY (`supplierID`) REFERENCES `supplier` (`supplierID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `productsupplierlocation` (
  `productID` varchar(15) NOT NULL,
  `supplierID` varchar(15) NOT NULL,
  `locationID` varchar(15) NOT NULL,
  `supplierAreaUnitPrice` double DEFAULT NULL,
