  CONSTRAINT `productIDPSLP` FOREIGN KEY (`productID`) REFERENCES `product` (`productID`),
  CONSTRAINT `supplierIDPSPS` FOREIGN KEY (`supplierID`) REFERENCES `supplier` (`supplierID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `producttype` (
  `productTypeID` varchar(15) NOT NULL,
  `productLineID` varchar(15) DEFAULT NULL,
  `name` varchar(200) DEFAULT NULL,
  `description` varchar(1500) DEFAULT NULL,
  PRIMARY KEY (`productTypeID`),
  KEY `productLineID_idx` (`productLineID`),
  CONSTRAINT `productLineID` FOREIGN KEY (`productLineID`) REFERENCES `productline` (`productLineID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `produitexcel` (
  `produitID` int NOT NULL AUTO_INCREMENT,
