  `ligneProduit` varchar(255) DEFAULT NULL,
  `typeProduit` varchar(255) DEFAULT NULL,
  `produit` varchar(255) DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `prix` double DEFAULT NULL,
  PRIMARY KEY (`produitID`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

CREATE TABLE `promotion` (
  `promotionID` varchar(15) NOT NULL,
  `brokerID` varchar(15) NOT NULL,
  `brokerContactID` varchar(15) NOT NULL,
  `startDate` datetime DEFAULT NULL,
  `endDate` datetime DEFAULT NULL,
  PRIMARY KEY (`promotionID`),
  KEY `brokerID_idx` (`brokerID`),
  KEY `brokerContactID_Promo_idx` (`brokerContactID`),
  CONSTRAINT `brokerContactID_Promo` FOREIGN KEY (`brokerContactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `brokerID_Promo` FOREIGN KEY (`brokerID`) REFERENCES `broker` (`brokerID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `promotiondetails` (
  `promotionID` varchar(15) NOT NULL,
