  CONSTRAINT `productID_PromoDet` FOREIGN KEY (`productID`) REFERENCES `product` (`productID`),
  CONSTRAINT `promotionID_PromoDet` FOREIGN KEY (`promotionID`) REFERENCES `promotion` (`promotionID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `purchase` (
  `purchaseID` varchar(15) NOT NULL,
  `brokerID` varchar(15) NOT NULL,
  `brokerContactID` varchar(15) NOT NULL,
  `transporterID` varchar(15) DEFAULT NULL,
  `transporterContactID` varchar(15) DEFAULT NULL,
  `supplierID` varchar(15) NOT NULL,
  `supplierContactID` varchar(15) NOT NULL,
  `storeID` varchar(15) DEFAULT NULL,
  `purchaseDate` datetime DEFAULT NULL,
  `receivedDate` datetime DEFAULT NULL,
  `transportCost` double DEFAULT NULL,
  `total` double DEFAULT NULL,
  `subTotal` double DEFAULT NULL,
  `tax` double DEFAULT NULL,
  PRIMARY KEY (`purchaseID`),
  KEY `brokerID_PB_idx` (`brokerID`),
  KEY `brokerContactID_PBC_idx` (`brokerContactID`),
  KEY `transporterID_PT_idx` (`transporterID`),
  KEY `supplierID_PS_idx` (`supplierID`),
  KEY `supplierContactID_PSC_idx` (`supplierContactID`),
  KEY `transporterContactID_PTC_idx` (`transporterContactID`),
  KEY `storeID_PST_idx` (`storeID`),
  CONSTRAINT `brokerContactID_PBC` FOREIGN KEY (`brokerContactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `brokerID_PB` FOREIGN KEY (`brokerID`) REFERENCES `broker` (`brokerID`),
  CONSTRAINT `storeID_PST` FOREIGN KEY (`storeID`) REFERENCES `store` (`storeID`),
  CONSTRAINT `supplierContactID_PSC` FOREIGN KEY (`supplierContactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `supplierID_PS` FOREIGN KEY (`supplierID`) REFERENCES `supplier` (`supplierID`),
  CONSTRAINT `transporterContactID_PTC` FOREIGN KEY (`transporterContactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `transporterID_PT` FOREIGN KEY (`transporterID`) REFERENCES `transporter` (`transporterID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `purchasedetails` (
  `purchaseID` varchar(15) NOT NULL,
  `productID` varchar(15) NOT NULL,
  `quantity` int DEFAULT NULL,
  `unitPrice` double DEFAULT NULL,
  `total` double DEFAULT NULL,
  PRIMARY KEY (`purchaseID`,`productID`),
  KEY `productID` (`productID`),
  CONSTRAINT `productID_PDP` FOREIGN KEY (`productID`) REFERENCES `product` (`productID`),
  CONSTRAINT `purchaseID_PDP` FOREIGN KEY (`purchaseID`) REFERENCES `purchase` (`purchaseID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `quote` (
  `quoteID` varchar(15) NOT NULL,
  `clientID` varchar(15) DEFAULT NULL,
  `clientContactID` varchar(15) DEFAULT NULL,
  `brokerID` varchar(15) DEFAULT NULL,
  `createdDate` datetime DEFAULT NULL,
  `nbrOfItems` int DEFAULT '0',
  `transportCost` double DEFAULT NULL,
  `tax` double DEFAULT NULL,
  `subTotal` double DEFAULT NULL,
  `total` double DEFAULT NULL,
  `expiredDate` datetime DEFAULT NULL,
  `reminderDate` datetime DEFAULT NULL,
  `followUpDate` datetime DEFAULT NULL,
  `status` varchar(80) DEFAULT NULL,
  PRIMARY KEY (`quoteID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `quotedetails` (
  `quoteID` varchar(15) NOT NULL,
  `productID` varchar(15) NOT NULL,
