  PRIMARY KEY (`regionID`),
  KEY `countryID_RC_idx` (`countryID`),
  CONSTRAINT `countryID_RC` FOREIGN KEY (`countryID`) REFERENCES `country` (`countryID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `sell` (
  `sellID` varchar(15) NOT NULL,
  `brokerID` varchar(15) DEFAULT 'BRK_0000000001',
  `brokerContactID` varchar(15) DEFAULT NULL,
  `clientID` varchar(15) DEFAULT NULL,
  `clientContactID` varchar(15) DEFAULT NULL,
  `transporterID` varchar(15) DEFAULT NULL,
  `transporterContactID` varchar(15) DEFAULT NULL,
  `sellDate` datetime DEFAULT NULL,
  `total` double DEFAULT NULL,
  `subTotal` double DEFAULT NULL,
  `tax` double DEFAULT NULL,
  `transportCost` double DEFAULT NULL,
  `completed` bit(1) DEFAULT b'0',
  PRIMARY KEY (`sellID`),
  KEY `clientID_SC_idx` (`clientID`),
  KEY `clientContactID_SCC_idx` (`clientContactID`),
  KEY `brokerID_SCB_idx` (`brokerID`),
  KEY `brokerContactID_SCBC_idx` (`brokerContactID`),
  KEY `transporterContactID_STC_idx` (`transporterContactID`),
  KEY `transporterID_idx` (`transporterID`),
  CONSTRAINT `brokerContactID_SBC` FOREIGN KEY (`brokerContactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `brokerID_SB` FOREIGN KEY (`brokerID`) REFERENCES `broker` (`brokerID`),
  CONSTRAINT `clientContactID_SCC` FOREIGN KEY (`clientContactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `clientID_SC` FOREIGN KEY (`clientID`) REFERENCES `client` (`clientID`),
  CONSTRAINT `transporterContactID_STC` FOREIGN KEY (`transporterContactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `transporterID` FOREIGN KEY (`transporterID`) REFERENCES `transporter` (`transporterID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `selldetails` (
  `sellID` varchar(15) NOT NULL,
  `productID` varchar(15) NOT NULL,
  `lenghtID` varchar(15) DEFAULT NULL,
  `quantity` int DEFAULT NULL,
  `unitPrice` double DEFAULT NULL,
  `total` double DEFAULT NULL,
  PRIMARY KEY (`sellID`,`productID`),
  KEY `sellID_SDS_idx` (`sellID`),
  KEY `productID_SDP_idx` (`productID`),
  CONSTRAINT `productID_SDP` FOREIGN KEY (`productID`) REFERENCES `product` (`productID`),
  CONSTRAINT `sellID_SDS` FOREIGN KEY (`sellID`) REFERENCES `sell` (`sellID`)
