  `clientContactID` varchar(15) NOT NULL,
  `shipmentDate` datetime DEFAULT NULL,
  `receivedDate` datetime DEFAULT NULL,
  `expectedDaysDuration` int DEFAULT NULL,
  `status` varchar(1500) DEFAULT NULL,
  `clientSignature` mediumblob,
  `transportCost` double DEFAULT NULL,
  `total` double DEFAULT NULL,
  `subTotal` double DEFAULT NULL,
  `tax` double DEFAULT NULL,
  PRIMARY KEY (`shipmentID`),
  UNIQUE KEY `sellID_SHS_unique` (`sellID`),
  KEY `brokerID_SHB_idx` (`brokerID`),
  KEY `brokerContactID_SHBC_idx` (`brokerContactID`),
  KEY `transporterID_SHT_idx` (`transporterID`),
  KEY `clientID_SHC_idx` (`clientID`),
  KEY `sellID_SHP_idx` (`sellID`),
  KEY `clientContactID_SCC_idx` (`clientContactID`),
  KEY `transporterContactID_STC_idx` (`transporterContactID`),
  KEY `transportID_SHT_idx` (`transportID`),
  CONSTRAINT `brokerContactID_SHBC` FOREIGN KEY (`brokerContactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `brokerID_SHB` FOREIGN KEY (`brokerID`) REFERENCES `broker` (`brokerID`),
  CONSTRAINT `clientContactID_SHCC` FOREIGN KEY (`clientContactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `clientID_SHC` FOREIGN KEY (`clientID`) REFERENCES `client` (`clientID`),
  CONSTRAINT `sellID_SHP` FOREIGN KEY (`sellID`) REFERENCES `sell` (`sellID`),
  CONSTRAINT `transporterContactID_SHTC` FOREIGN KEY (`transporterContactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `transporterID_SHT` FOREIGN KEY (`transporterID`) REFERENCES `transporter` (`transporterID`),
  CONSTRAINT `transportID_SHT` FOREIGN KEY (`transportID`) REFERENCES `transport` (`transportID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `shipmentdetails` (
  `shipmentID` varchar(15) NOT NULL,
