  KEY `lenghtID_SHDL_idx` (`lenghtID`),
  CONSTRAINT `lenghtID_SHDL` FOREIGN KEY (`lenghtID`) REFERENCES `lenghtlookup` (`lenghtID`),
  CONSTRAINT `productID_SHDP` FOREIGN KEY (`productID`) REFERENCES `product` (`productID`),
  CONSTRAINT `shipmentID_SHDSH` FOREIGN KEY (`shipmentID`) REFERENCES `shipment` (`shipmentID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

