  PRIMARY KEY (`supplierID`),
  KEY `addressID_SA_idx` (`addressID`),
  KEY `supplierTypeID_SST_idx` (`supplierTypeID`),
  CONSTRAINT `addressIDSA` FOREIGN KEY (`addressID`) REFERENCES `address` (`addressID`),
  CONSTRAINT `supplierTypeIDSST` FOREIGN KEY (`supplierTypeID`) REFERENCES `suppliertype` (`supplierTypeID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

