  KEY `contactID_SCC_idx` (`contactID`),
  CONSTRAINT `contactIDSCC` FOREIGN KEY (`contactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `supplierIDSCS` FOREIGN KEY (`supplierID`) REFERENCES `supplier` (`supplierID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `supplierreview` (
  `supplierReviewID` varchar(15) NOT NULL,
