  `clientID` varchar(15) DEFAULT NULL,
  `contactID` varchar(15) NOT NULL,
  `ratingValue` int NOT NULL,
  `evaluatedDate` datetime DEFAULT NULL,
  `reviewMessage` varchar(1500) DEFAULT NULL,
  PRIMARY KEY (`supplierReviewID`),
  KEY `supplierID_SRS_idx` (`supplierID`),
  KEY `clientID_SRCC_idx` (`clientID`),
  KEY `contactID_SRCC_idx` (`contactID`),
  CONSTRAINT `clientID_SRCC` FOREIGN KEY (`clientID`) REFERENCES `client` (`clientID`),
  CONSTRAINT `contactID_SRCC` FOREIGN KEY (`contactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `supplierID_SRS` FOREIGN KEY (`supplierID`) REFERENCES `supplier` (`supplierID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `suppliertype` (
  `supplierTypeID` varchar(15) NOT NULL,
  `name` varchar(45) DEFAULT NULL,
