  `destinationCountry` varchar(60) DEFAULT NULL,
  PRIMARY KEY (`trajectID`),
  KEY `zoneID_TRJZ_idx` (`zoneID`),
  CONSTRAINT `zoneID_TRJZ` FOREIGN KEY (`zoneID`) REFERENCES `zone` (`zoneID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `transaction` (
  `transactionID` varchar(15) NOT NULL,
  `clientID` varchar(15) NOT NULL,
  `clientContactID` varchar(15) NOT NULL,
  `sellID` varchar(15) DEFAULT NULL,
  `transactionDate` datetime NOT NULL,
  `creditCardNbr` varchar(20) DEFAULT NULL,
  `mobilePhoneNbr` varchar(20) DEFAULT NULL,
  `phoneCountryCode` varchar(5) DEFAULT NULL,
  `brokerPaymentID` varchar(30) DEFAULT NULL,
  `brokerTransactionDate` varchar(30) DEFAULT NULL,
  `signature` varchar(50) DEFAULT NULL,
  `message` varchar(250) DEFAULT NULL,
  `status` varchar(30) DEFAULT NULL,
  `result` varchar(5) DEFAULT NULL,
  `total` double DEFAULT NULL,
  PRIMARY KEY (`transactionID`),
  KEY `clientID_CTR_idx` (`clientID`),
  KEY `clientContactID_CCTR_idx` (`clientContactID`),
  KEY `sellID_STR_idx` (`sellID`),
  CONSTRAINT `clientContactID_CCTR` FOREIGN KEY (`clientContactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `clientID_CTR` FOREIGN KEY (`clientID`) REFERENCES `client` (`clientID`),
  CONSTRAINT `sellID_STR` FOREIGN KEY (`sellID`) REFERENCES `sell` (`sellID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `transport` (
  `transportID` varchar(15) NOT NULL,
  `originAddressID` varchar(15) NOT NULL,
  `destinationAddressID` varchar(15) NOT NULL,
  `transporterID` varchar(15) NOT NULL,
  `departureDate` datetime DEFAULT NULL,
  `arrivalDate` datetime DEFAULT NULL,
  `transportTotalCost` double DEFAULT NULL,
  PRIMARY KEY (`transportID`),
  KEY `originAddressID_TA_idx` (`originAddressID`),
  KEY `destinationAddressID_TA_idx` (`destinationAddressID`),
  KEY `transporterID_TTP_idx` (`transporterID`),
  CONSTRAINT `destinationAddressIDTA` FOREIGN KEY (`destinationAddressID`) REFERENCES `address` (`addressID`),
  CONSTRAINT `originAddressIDTA` FOREIGN KEY (`originAddressID`) REFERENCES `address` (`addressID`),
  CONSTRAINT `transporterIDTTP` FOREIGN KEY (`transporterID`) REFERENCES `transporter` (`transporterID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `transporter` (
  `transporterID` varchar(15) NOT NULL,
  `addressID` varchar(15) NOT NULL,
  `transporterTypeID` varchar(15) DEFAULT NULL,
  `name` varchar(45) DEFAULT NULL,
  `businessDescription` varchar(250) DEFAULT NULL,
  PRIMARY KEY (`transporterID`),
  KEY `addressID_TPA_idx` (`addressID`),
  KEY `transporterTypeID_TPTPT_idx` (`transporterTypeID`),
  CONSTRAINT `addressIDTPA` FOREIGN KEY (`addressID`) REFERENCES `address` (`addressID`),
  CONSTRAINT `transporterTypeIDTPTPT` FOREIGN KEY (`transporterTypeID`) REFERENCES `transportertype` (`transporterTypeID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `transportercontact` (
  `transporterID` varchar(15) NOT NULL,
  `contactID` varchar(15) NOT NULL,
  `startedDate` datetime DEFAULT NULL,
  `endedDate` datetime DEFAULT NULL,
  PRIMARY KEY (`transporterID`,`contactID`),
  KEY `contactID_TPCC_idx` (`contactID`),
  CONSTRAINT `contactIDTPCC` FOREIGN KEY (`contactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `transporterIDTPCTP` FOREIGN KEY (`transporterID`) REFERENCES `transporter` (`transporterID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `transportercostpertraject` (
  `trajectID` varchar(15) NOT NULL,
  `weightLimitID` varchar(15) NOT NULL,
  `transporterID` varchar(15) NOT NULL,
  `transportCost` double DEFAULT NULL,
  PRIMARY KEY (`trajectID`,`weightLimitID`,`transporterID`),
  KEY `weightLimitID_TCPTWL` (`weightLimitID`),
  KEY `transporterID_TCPTTPR` (`transporterID`),
  CONSTRAINT `trajectID_TCPTTRJ` FOREIGN KEY (`trajectID`) REFERENCES `traject` (`trajectID`) ON UPDATE CASCADE,
  CONSTRAINT `transporterID_TCPTTPR` FOREIGN KEY (`transporterID`) REFERENCES `transporter` (`transporterID`) ON UPDATE CASCADE,
  CONSTRAINT `weightLimitID_TCPTWL` FOREIGN KEY (`weightLimitID`) REFERENCES `weightlimit` (`weightLimitID`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `transportertype` (
  `transporterTypeID` varchar(15) NOT NULL,
  `name` varchar(45) DEFAULT NULL,
  `description` varchar(250) DEFAULT NULL,
  PRIMARY KEY (`transporterTypeID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `usercreator` (
