  CONSTRAINT `brokerID_WLB` FOREIGN KEY (`brokerID`) REFERENCES `broker` (`brokerID`),
  CONSTRAINT `clientContactID_WLCC` FOREIGN KEY (`clientContactID`) REFERENCES `contact` (`contactID`),
  CONSTRAINT `clientID_WLC` FOREIGN KEY (`clientID`) REFERENCES `client` (`clientID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `wishlistdetails` (
  `wishListID` varchar(15) NOT NULL,
  `productID` varchar(15) NOT NULL,
  `lenghtID` varchar(15) DEFAULT 'LENGHT_00000001',
  `giverFirstName` varchar(60) DEFAULT NULL,
  `giverLastName` varchar(60) DEFAULT NULL,
  `giverEmail` varchar(80) DEFAULT NULL,
  `isPaid` varchar(1) NOT NULL DEFAULT 'N',
  `comments` varchar(500) DEFAULT NULL,
  `unitPrice` double DEFAULT NULL,
  `unitTax` double DEFAULT NULL,
  `quantity` int DEFAULT NULL,
  `total` double DEFAULT NULL,
  PRIMARY KEY (`wishListID`,`productID`),
  KEY `productID_WLDP_idx` (`productID`),
  KEY `lenghtID_WLDL_idx` (`lenghtID`),
  CONSTRAINT `lenghtID_WLDL` FOREIGN KEY (`lenghtID`) REFERENCES `lenghtlookup` (`lenghtID`),
  CONSTRAINT `productID_WLDP` FOREIGN KEY (`productID`) REFERENCES `product` (`productID`),
  CONSTRAINT `wishListID_WLDWL` FOREIGN KEY (`wishListID`) REFERENCES `wishlist` (`wishListID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `wishlistsell` (
  `wishListID` varchar(15) NOT NULL,
  `sellID` varchar(15) NOT NULL,
  `giverComments` varchar(80) DEFAULT NULL,
  PRIMARY KEY (`wishListID`,`sellID`),
  KEY `sellID_WLSS_idx` (`sellID`),
  CONSTRAINT `sellID_WLSS` FOREIGN KEY (`sellID`) REFERENCES `sell` (`sellID`),
  CONSTRAINT `wishListID_WLSWL` FOREIGN KEY (`wishListID`) REFERENCES `wishlist` (`wishListID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `zone` (
  `zoneID` varchar(15) NOT NULL,
  `name` varchar(80) DEFAULT NULL,
  `description` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`zoneID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

SET FOREIGN_KEY_CHECKS = 1;
